<?php
require __DIR__ . '/config/db.php';require __DIR__ . '/sourcing-functions.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){header('Location: rfq-list.php');exit;}$pdo=db();$q=$pdo->prepare('SELECT * FROM rfqs WHERE id=? LIMIT 1');$q->execute([$id]);$rfq=$q->fetch();if(!$rfq){http_response_code(404);exit('RFQ not found.');}$s=$pdo->prepare('SELECT rs.id supplier_row_id,rs.supplier_name,rs.contact_name,rs.contact_email,r.* FROM rfq_suppliers rs LEFT JOIN rfq_supplier_responses r ON r.rfq_supplier_id=rs.id AND r.is_latest=1 WHERE rs.rfq_id=? ORDER BY rs.sort_order,rs.id');$s->execute([$id]);$rows=$s->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Responses | <?= sourcing_h($rfq['rfq_number']) ?></title><style>body{margin:0;background:#f4f7fa;font:14px Arial;color:#17212b}.top{background:#0c2340;color:#fff;padding:18px}.wrap,.topin{max-width:1200px;margin:auto}.wrap{padding:22px}h1{color:#0c2340}.toolbar{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.btn{display:inline-block;text-decoration:none;border-radius:8px;padding:9px 12px;font-weight:700;background:#0c2340;color:#fff}.card{background:#fff;border:1px solid #d9e0e6;border-radius:12px;padding:17px;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.item b{display:block;font-size:11px;color:#66717d;text-transform:uppercase;margin-bottom:4px}.none{color:#8a2424;font-weight:700}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}.wrap{padding:13px}}@media(max-width:500px){.grid{grid-template-columns:1fr}}</style></head><body><div class="top"><div class="topin"><strong>Lowe Chemical Company | Internal Sourcing</strong></div></div><main class="wrap"><div class="toolbar"><div><h1><?= sourcing_h($rfq['rfq_number']) ?> Supplier Responses</h1><div><?= sourcing_h($rfq['product_name']) ?></div></div><div><?=workflow_back_link('btn')?> <a class="btn" href="rfq-comparison.php?id=<?= (int)$id ?>">Compare Quotes</a> <a class="btn" href="rfq-list.php">RFQ List</a></div></div><?php foreach($rows as $r):?><section class="card"><h2><?= sourcing_h($r['supplier_name']) ?></h2><?php if(empty($r['id'])):?><div class="none">No supplier response received yet.</div><?php else:?><div class="grid"><div class="item"><b>Price</b><?= sourcing_h($r['price'].' '.$r['price_unit']) ?></div><div class="item"><b>Packaging</b><?= sourcing_h((string)$r['packaging']) ?></div><div class="item"><b>Container Weight</b><?= sourcing_h((string)$r['container_weight']) ?></div><div class="item"><b>Freight Method</b><?= sourcing_h((string)$r['freight_method']) ?></div><div class="item"><b>FOB Location</b><?= sourcing_h((string)$r['fob_location']) ?></div><div class="item"><b>Freight/Surcharges</b><?= sourcing_h((string)$r['freight_surcharges']) ?></div><div class="item"><b>Minimum Order</b><?= sourcing_h((string)$r['minimum_order']) ?></div><div class="item"><b>Lead Time</b><?= sourcing_h((string)$r['lead_time']) ?></div><div class="item"><b>Availability</b><?= sourcing_h((string)$r['availability']) ?></div><div class="item"><b>Payment Terms</b><?= sourcing_h((string)$r['payment_terms']) ?></div><div class="item"><b>Country of Origin</b><?= sourcing_h((string)$r['country_of_origin']) ?></div><div class="item"><b>Manufacturer</b><?= sourcing_h((string)$r['manufacturer']) ?></div><div class="item"><b>Quote Expiration</b><?= sourcing_h((string)$r['quote_expiration']) ?></div><div class="item"><b>Submitted</b><?= sourcing_h((string)$r['submitted_at']) ?></div></div><?php if(!empty($r['notes'])):?><p><b>Notes:</b> <?= nl2br(sourcing_h($r['notes'])) ?></p><?php endif;?><?php endif;?></section><?php endforeach;?></main></body></html>
